import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const container = new Group();
  const timeline = gsap.timeline();

  // Create subtle backdrop as per W-PCP design doctrine (preventing FLAT_VOID)
  const backdropGeo = new PlaneGeometry(8, 6.5);
  const backdropMat = new MeshBasicNodeMaterial();

  // Create beautiful rich gradient from #16161d (ink) to #0b0b10 (surface) with an accent hint
  const vUv = uv();
  const inkColor = vec3(0.086, 0.086, 0.114);    // #16161d
  const surfaceColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const accentColor = vec3(1.0, 0.165, 0.22);     // #ff2a38

  // Gentle radial glow contribution from the red accent in bottom left corner
  const radialGlow = vUv.distance(vec3(0.0, 0.0, 0.0)).oneMinus().smoothstep(0.4, 1.0).mul(0.12);
  const finalGradient = mix(inkColor, surfaceColor, vUv.y).add(accentColor.mul(radialGlow));
  backdropMat.colorNode = vec4(finalGradient, 1.0);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // Setup main interactive billboard sprite card
  const cardGroup = new Group();
  container.add(cardGroup);

  // Aspect ratio calculated from atlas region 512x320 = 1.6
  const cardWidth = 1.6 * 1.3;
  const cardHeight = 1.3;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardGroup.add(cardMesh);

  // Load accent illustration if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      cardMat.colorNode = texture;
      cardMat.needsUpdate = true;
    }).catch(err => console.warn('Texture failed to load:', err));
  } else {
    // Elegant fallback translucent plate
    cardMat.colorNode = vec4(surfaceColor, 0.85);
  }

  // Create typography
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineCopy = textItems.find(t => t.role === 'headline' || t.role === 'title')?.text ?? "Collection 1";

  // Create clean serif layout (Lora 400/600 visual equivalent)
  const textObj = ctx.fontAtlas.createText(headlineCopy, {
    fontSize: 0.16,
    color: '#e8ecf2', // paper
    align: 'center'
  });
  // Position text overlaying slightly in front of the textured plate
  textObj.position.set(0, -0.15, 0.08);
  cardGroup.add(textObj);

  // Gentle floating animation to deliver dimensional weight
  timeline.to(cardGroup.position, {
    y: '+=0.04',
    duration: 3.2,
    ease: 'sine.inOut',
    repeat: -1,
    yoyo: true
  });

  // Entrance settle animation
  gsap.fromTo(cardGroup.scale, 
    { x: 0.88, y: 0.88, z: 0.88 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 1.4, ease: 'power4.out' }
  );

  // Cleanup cycle
  container.userData = {
    handlers: {},
    cleanup: () => {
      timeline.kill();
      gsap.killTweensOf(cardGroup.position);
      gsap.killTweensOf(cardGroup.scale);
      cardGeo.dispose();
      cardMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
    }
  };

  return container;
}
